from taf.sbts.oam.coam.admin import admin
from taf.transport.ssh import ssh
from taf.config.testline.airscale import CommonUnit, CoreUnit

from taf.ul.kpi_selector.btss.classical.Rmod import Rmod
from taf.ul.kpi_selector.btss.classical.Smod import Smod
from taf.ul.kpi_selector.btss.classical.Cell import Cell, CELL_ID_PARAM_NAMES
from taf.ul.kpi_selector.utilities.kpi_logger import log_input_and_output, log_env_state
from taf.ul.kpi_selector.utilities.sw_stream.interface import get_sw_stream
from taf.ul.kpi_selector.btss.exceptions import ConfigTypeNotFound, MissingObjectError


class Bts(object):
    """
    Representation of Classical BTS parameters. Gets all necessary parameters from BTS and test line configuration file
    to set proper timeout for operations.
    """

    ROBOT_LIBRARY_SCOPE = 'TEST CASE'

    def __init__(self, tl, connection):
        self._tl = tl
        self._type = "GNB" if self._tl.gnbs else "ENB"
        self._connection = connection
        self._admin = admin()
        self._ssh = ssh()
        self._setup_mode = None
        self._stream = None
        self._radio_protocol = None
        self._is_full_rack = None
        self._rf_sharing = None
        self._is_multi_rat = None
        self._is_rmods_target_bd_sw_version_different = None
        self._is_graceful_cell_shutdown_enabled = None

        self._smods = None
        self._smod_hw_types = None
        self._bbmods = None
        self._bbmod_hw_types = None
        self._rmods = None
        self._rmod_hw_types = None
        self._rmod_scm_flags = None
        self._rmod_sw_versions = None

        self._nr_cells = None
        self._lte_cells = None
        self._wcdma_cells = None
        self._gsm_cells = None
        self._cells = None
        self._cell_technologies = None
        self._cell_types = None

    @property
    def setup_mode(self):
        """
        Returns BTS configuration mode: SA/NSA/NSA+SA.
        :return: BTS configuration e.g, "SA"
        :rtype: str
        """
        if not self._setup_mode:
            self._setup_mode = self._get_bts_setup_mode()

        log_env_state("Detected setup mode: {}. ".format(self._setup_mode))

        return self._setup_mode

    @property
    def radio_protocol(self):
        """
        Returns radio protocol type.
        :return: Radio protocol type e.g, "CPRI"
        :rtype: str
        """
        if not self._radio_protocol:
            protocols = [rmod.protocol for rmod in self.rmods]
            if all([protocol == protocols[0] for protocol in protocols]):  # noqa: C419
                self._radio_protocol = protocols[0]
            else:
                self._radio_protocol = "MIX"

        log_env_state("Detected rmods' protocol: {}".format(self._radio_protocol))

        return self._radio_protocol

    @property
    def stream(self):
        """
        Returns current active stream on BTS.
        :return: Current stream, e.g "SBTS22R1"
        :rtype: str
        """
        if not self._stream:
            self._stream = get_sw_stream(device=self._type)

        log_env_state("Detected sw stream: {}".format(self._stream))

        return self._stream

    @property
    def nr_cells(self):
        """
        Representation of NR cells on BTS
        :return: list of cells from taf.ul.kpi_selector.btss.classical.Cell
        :rtype: list
        """
        if self._nr_cells is None:
            self._nr_cells = self._get_cells(cell_type='nr')

        log_env_state("Detected NR cells: {}".format([str(cell) for cell in self._nr_cells]))

        return self._nr_cells

    @property
    def number_of_nr_cells(self):
        """
        Returns number of NR cells on BTS.
        :return: Number of NR cells
        :rtype: int
        """
        return len(self.nr_cells)

    @property
    def lte_cells(self):
        """
        Representation of LTE cells on BTS
        :return: list of cells from taf.ul.kpi_selector.btss.classical.Cell
        :rtype: list
        """
        if self._lte_cells is None:
            self._lte_cells = self._get_cells(cell_type='lte')

        log_env_state("Detected LTE cells: {}".format([str(cell) for cell in self._lte_cells]))

        return self._lte_cells

    @property
    def number_of_lte_cells(self):
        """
        Returns number of LTE cells on BTS.
        :return: Number of LTE cells
        :rtype: int
        """
        return len(self.lte_cells)

    @property
    def wcdma_cells(self):
        """
        Representation of WCDMA cells on BTS
        :return: list of cells from taf.ul.kpi_selector.btss.classical.Cell
        :rtype: list
        """
        if self._wcdma_cells is None:
            self._wcdma_cells = self._get_cells(cell_type='wcdma')

        log_env_state("Detected WCDMA cells: {}".format([str(cell) for cell in self._wcdma_cells]))

        return self._wcdma_cells

    @property
    def number_of_wcdma_cells(self):
        """
        Returns number of WCDMA cells on BTS.
        :return: Number of WCDMA cells
        :rtype: int
        """
        return len(self.wcdma_cells)

    @property
    def gsm_cells(self):
        """
        Representation of GSM cells on BTS
        :return: list of cells from taf.ul.kpi_selector.btss.classical.Cell
        :rtype: list
        """
        if self._gsm_cells is None:
            self._gsm_cells = self._get_cells(cell_type='gsm')

        log_env_state("Detected GSM cells: {}".format([str(cell) for cell in self._gsm_cells]))

        return self._gsm_cells

    @property
    def number_of_gsm_cells(self):
        """
        Returns number of GSM cells on BTS.
        :return: Number of GSM cells
        :rtype: int
        """
        return len(self.gsm_cells)

    @property
    def cells(self):
        """
        Representation of all cells on BTS
        :return: list of cells from taf.ul.kpi_selector.btss.classical.Cell
        :rtype: list
        """
        if self._cells is None:
            self._cells = self.nr_cells + self.lte_cells + self.wcdma_cells + self.gsm_cells

        return self._cells

    @property
    def number_of_cells(self):
        """
        Returns number of all cells on BTS.
        :return: Number of all cells
        :rtype: int
        """
        return len(self.cells)

    @property
    def number_of_super_cells(self):
        """
        Returns number of super cells on BTS.
        :return: Number of super cells
        :rtype: int
        """
        return sum([cell.is_super_cell for cell in self.cells])

    @property
    def cell_technologies(self):
        """
        Returns cells' technologies i.e. "FDD", "TDD" or "MIX"
        :return: cells' technologies
        :rtype: string
        """
        if not self._cell_technologies:
            all_technologies = [cell.technology for cell in self.cells]
            self._cell_technologies = list(set(all_technologies))[0] if len(set(all_technologies)) == 1 else "MIX"

        log_env_state("Detected cell technologies: {}".format(self._cell_technologies))

        return self._cell_technologies

    @property
    def smods(self):
        """
        Returns BTS system modules objects based on init content.
        :return: Smod objects
        :rtype: list of smods
        """
        if not self._smods:
            self._smods = self._get_system_modules()

        log_env_state("Detected smods: {}".format(self._smods))

        return self._smods

    @property
    def smod_hw_types(self):
        """
        Returns BTS system modules types
        :return: Smod types, e.g ["ASIK"]
        :rtype: list
        """
        if not self._smod_hw_types:
            self._smod_hw_types = [smod.hardware_type for smod in self.smods]

        log_env_state("Detected smod hardware types: {}".format(self._smod_hw_types))

        return self._smod_hw_types

    @property
    def number_of_smods(self):
        """
        Returns number of BTS system modules from init
        :return: Number of smods
        :rtype: int
        """
        log_env_state("Number of smods is: {}".format(len(self.smods)))

        return len(self.smods)

    @property
    def bbmods(self):
        """
        Returns BTS baseband modules objects based on init content.
        :return: Bbmod objects
        :rtype: list of bbmods
        """
        if not self._bbmods:
            self._bbmods = []
            for smod in self.smods:
                if smod.capacity_units:
                    self._bbmods.extend(smod.capacity_units)

        log_env_state("Detected bbmods: {}".format(self._bbmods))

        return self._bbmods

    @property
    def bbmod_hw_types(self):
        """
        Returns BTS baseband module types
        :return: Bbmod types, e.g ["ABIL"]
        :rtype: list of str
        """
        if not self._bbmod_hw_types:
            self._bbmod_hw_types = list(set([bbmod.hardware_type for bbmod in self.bbmods])) if self.bbmods else []  # noqa: C403

        log_env_state("Detected bbmods hardware types: {}".format(self._bbmod_hw_types))

        return self._bbmod_hw_types

    @property
    def number_of_bbmods(self):
        """
        Returns BTS number of baseband modules from init.
        :return: Number of bbmods
        :rtype: int
        """
        log_env_state("Number of bbmods: {}".format(len(self.bbmods)))

        return len(self.bbmods)

    @property
    def rmods(self):
        """
        Returns BTS radios objects based on init content.
        :return: list of RU class instances
        :rtype: list
        """
        if not self._rmods:
            self._rmods = self._get_rmods()

        log_env_state("Detected rmods: {}".format([str(rmod) for rmod in self._rmods]))

        return self._rmods

    @property
    def number_of_rmods(self):
        """
        Returns number of rmods from init
        :return: Number of rmods
        :rtype: int
        """
        log_env_state("Number of rmods: {}".format(len(self.rmods)))

        return len(self.rmods)

    @property
    def rmod_hw_types(self):
        """
        Returns BTS rmods' types
        :return: rmods' types, e.g ["AEQN", "AEQA", "AEQO"]
        :rtype: list of str
        """
        if not self._rmod_hw_types:
            self._rmod_hw_types = [rmod.radio_type for rmod in self.rmods]

        log_env_state("Detected rmods' hardware types {}".format(self._rmod_hw_types))

        return self._rmod_hw_types

    @property
    def rmod_sw_versions(self):
        """
        Returns radio units' current softwares using system module's targetBD.
        :return: List of radio unit softwares matched with tu type, e.g [{'AEQN': 'RF.5GL3.trunk.20210921.011'},
                                                                         {'AEQN': 'RF.5GL3.trunk.20210921.011'}]
        :rtype: List[Dict[str, str]]
        """
        if not self._rmod_sw_versions:
            self._rmod_sw_versions = [{rmod.radio_type: rmod.current_sw_version} for rmod in self.rmods]

        log_env_state("Detected rmods' software versions: {}".format(self._rmod_sw_versions))

        return self._rmod_sw_versions

    @property
    def rmod_scm_flags(self):
        """
        Returns list of radio modules' scm flags
        :return: List of RU types and its scm flags, e.g [{"AEQN": "rel5.1"}, {"AZQJ": "URM6"}]
        :rtype: list of dict
        """
        if not self._rmod_scm_flags:
            self._rmod_scm_flags = [{rmod.radio_type: rmod.scm_flag} for rmod in self.rmods]

        log_env_state("Detected rmods' scm flags: {}".format(self._rmod_scm_flags))

        return self._rmod_scm_flags

    @property
    def is_full_rack(self):
        """
        Decides whether test line is full rack: True if there is more than one smod, False otherwise
        :return: True when number of detected system modules is higher than 1, False otherwise
        :rtype: bool
        """
        if self._is_full_rack is None:
            self._is_full_rack = True if len(self.smods) > 1 else False

        log_env_state("Is test line full rack: {}".format(self._is_full_rack))

        return self._is_full_rack

    @property
    def is_multi_rat(self):
        """
        Checks whether test line is multi RAT
        :return: True if there is more than one RAT, False otherwise
        :rtype: bool
        """
        if self._is_multi_rat is None:
            rats = [rat for rat in ["lte", "wcdma", "gsm", "nr"] if
                    self._admin.get_cells_info(cell_type=rat, connection=self._connection)]
            self._is_multi_rat = True if len(rats) > 1 else False

        log_env_state("Is test line multi rat: {}".format(self._is_multi_rat))

        return self._is_multi_rat

    @property
    def rf_sharing(self):
        """
        Checks whether there is rf sharing on test line
        """
        if self._rf_sharing is None:
            self._rf_sharing = self._check_if_smod_external_exists_in_cablinks()

        log_env_state("Is rf sharing on test line: {}".format(self._rf_sharing))

        return self._rf_sharing

    @property
    def cell_types(self):
        """
        List of cell types, e.g. ["nr", "lte"]
        """
        if not self._cell_types:
            all_types = [cell.type for cell in self.cells]
            self._cell_types = list(set(all_types))

        return self._cell_types

    @property
    def is_rmods_target_bd_sw_version_different(self):
        """
        Checks if rmods sw versions collected from target bd are different than sw version collected
        directly from rmod units.
        """
        if self._is_rmods_target_bd_sw_version_different is None:
            self._is_rmods_target_bd_sw_version_different = all([rmod.is_target_bd_sw_version_different  # noqa: C419
                                                                 for rmod in self.rmods])

        log_env_state("Are rmods target bd sw versions different than admin sw versions: {}".format(
            self._is_rmods_target_bd_sw_version_different))

        return self._is_rmods_target_bd_sw_version_different

    @property
    def is_graceful_cell_shutdown_enabled(self):
        """
        Checks value of actGrflShdn parameter
        """
        if self._is_graceful_cell_shutdown_enabled is None:
            class_name = "NRBTS_A" if self._type == "GNB" else "LNBTS_A"
            info = self._admin.get_managed_objects(connection=self._connection, class_name=class_name)
            self._is_graceful_cell_shutdown_enabled = info[0]['parameters']['actGrflShdn']

        return self._is_graceful_cell_shutdown_enabled

    def set_up_parent_rmods_for_cells(self):
        """
        Sets up _parent_rmods attribute for cells
        """
        self._set_up_parent_rmods_for_cells()

    @log_input_and_output
    def _get_test_pc_of_provided_smod(self, smod):
        """
        Gets test pc of given system module from tesline configuration file
        :param smod: System module that user wants to find its test pc
        :type smod: CommonUnit instance object from taf.config.testline.airscale
        :return: TestPc data from testline configuration file
        :rtype: TestPc instance from taf.config.testline.testpc
        :raises: MissingObjectError if could not find test PC for provided smod
        """
        test_pcs = self._tl.test_pcs

        for test_pc in test_pcs:
            matched_connection = test_pc.connections[0] if isinstance(test_pc.connections[0], (CommonUnit, CoreUnit)) \
                else test_pc.connections[0].device
            if matched_connection == smod:
                return test_pc

        raise MissingObjectError("Could not find test PC that matches SMOD {} provided in `connections` attribute!".
                                 format(smod))

    @log_input_and_output
    def _get_rmods(self):
        """
        Gets BTS rmods objects based on init content.
        :return: list of Rmod instances
        :rtype: list(Rmod)
        """
        if self._tl.gnbs:
            if not self._tl.gnbs[0].dus[0].rus:
                return self._get_rmods_for_common_agent_setups()
            return [Rmod(rmod, self.smods, str(init_id)) for init_id, rmod in enumerate(self._tl.gnbs[0].dus[0].rus)]
        elif self._tl.enbs:
            return [Rmod(rmod, self.smods, str(init_id)) for init_id, rmod in enumerate(self._tl.enbs[0].rms)]

        raise ConfigTypeNotFound('Could not find gnbs nor enbs in configuration file. '
                                 'Please review your init file.')

    def _get_rmods_for_common_agent_setups(self):
        rmods = []
        airscale = self._tl.gnbs[0].dus[0].airscale
        smods = airscale.common_units or airscale.core_units
        for common_unit in smods:
            if hasattr(common_unit, 'capacity_units'):
                for capacity_unit in common_unit.capacity_units:
                    rmods.extend(capacity_unit.rus)
            else:
                rmods.extend(common_unit.rus)
        return [Rmod(rmod, self.smods, str(init_id)) for init_id, rmod in enumerate(list(set(rmods)))]

    @log_input_and_output
    def _get_system_modules(self):
        """
        Gets BTS system modules objects based on init content.
        :return: list of Smod instances
        :rtype: list(Smod)
        """
        try:
            smods = self._tl.gnbs[0].dus[0].airscale.common_units if self._tl.gnbs else \
                self._tl.enbs[0].system_module.common_units
            if not smods:
                smods = self._tl.gnbs[0].dus[0].airscale.core_units
            return [Smod(smod, self._get_test_pc_of_provided_smod(smod=smod)) for smod in smods]

        except AttributeError:
            raise ConfigTypeNotFound('Could not find gnbs nor enbs in configuration file. '
                                     'Please review your init file.')

    @log_input_and_output
    def _get_bts_setup_mode(self):
        """
        Gets value of gNbCuType parameter
        :return gnbCuType i.e. SA, NSA, SA+NSA
        :rtype: str
        """
        try:
            return self._admin.get_bts_info(connection=self._connection)["gNbCuType"]
        except KeyError:
            return "SA"

    def _set_up_parent_rmods_for_cells(self):  # noqa: C901
        radiomodules_info = self._admin.get_bts_info(connection=self._connection)['radioModules']
        rmods_info = radiomodules_info['rmod'] + radiomodules_info['asirmod']

        for cell in self.cells:
            parent_rmod_ids = []
            for rmod in rmods_info:
                rmod_id = rmod['id']['configuration'].split('/')[-1].split('-')[1]
                if rmod_id not in parent_rmod_ids:
                    for carrier in rmod['carrierList']:
                        if carrier['id']['configuration'].split('/')[-2] == f"{cell.class_name}-{cell.id}":
                            parent_rmod_ids.append(rmod_id)
                            break

            cell.parent_rmods = [rmod for rmod in self.rmods if rmod.id in parent_rmod_ids]
            log_env_state("From all found rmods: {} identified parent RMOD IDs: {} for cell: {}".format(
                [rmod.id for rmod in self.rmods], parent_rmod_ids, cell.id))

    def _check_if_smod_external_exists_in_cablinks(self):
        cablinks = self._admin.get_parameters_for_all(class_name="CABLINK", connection=self._connection)

        for cablink in cablinks:
            if "SMOD_EXT-" in cablink["firstEndpointDN"]:
                return True

        return False

    def _get_cells(self, cell_type):
        idx_param = self._get_name_of_id_param_depending_on_cell_type(cell_type)
        cells = []
        for cell_info in self._admin.get_cells_info(cell_type=cell_type, connection=self._connection):
            if idx_param is None:
                cells.append(Cell(cell_type, int(cell_info['id']['configuration'].split('-')[-1])))
            else:
                cells.append(Cell(cell_type, cell_info[idx_param]))
        return cells

    @staticmethod
    def _get_name_of_id_param_depending_on_cell_type(cell_type):
        return CELL_ID_PARAM_NAMES[cell_type]
